      "shortStory": "Konark Sun Temple (The Black Pagoda) is an architectural jewel located in Puri District, Konark, Odisha. Conceived as a colossal 24-wheeled chariot carrying the Sun God Surya across the heavens, pulled by 7 spirited horses. European mariners called it the 'Black Pagoda' because its dark iron lodestone tower was said to exer...",
      "history": "Constructed during 1250 CE (13th Century) under the royal patronage of Eastern Ganga Dynasty (King Narasimhadeva I). Conceived as a colossal 24-wheeled chariot carrying the Sun God Surya across the heavens, pulled by 7 spirited horses. European mariners called it the 'Black Pagoda' because its dark iron lodestone tower was said to exert magnetic pull on passing ships' navigational compasses. Legend attributes the final stone placement to 12-year-old child prodigy Dharmapada. Built using authentic materials: Khondalite Sandstone, Chlorite stone doorframes, Iron dowels and magnetic stone lodestone clamps.",
      "significance": "Konark Sun Temple (The Black Pagoda) is protected under the Archaeological Survey of India (ASI ID: E-OD-1, UNESCO: 246 (Inscribed 1984)). It stands as a testament to the engineering and cultural prowess of Odisha.",
