      "shortStory": "Group of Monuments at Mahabalipuram is an architectural jewel located in Chengalpattu District, Mamallapuram, Tamil Nadu. Built as the primary naval and merchant port of the Pallava Empire trading with Sri Lanka, Java, and China. 'Descent of the Ganges' is one of the world's largest open-air rock bas-reliefs, carved onto two monolithic boul...",
      "history": "Constructed during 7th – 8th Century CE under the royal patronage of Pallava Dynasty (Narasimhavarman I Mamalla & Rajasimha). Built as the primary naval and merchant port of the Pallava Empire trading with Sri Lanka, Java, and China. 'Descent of the Ganges' is one of the world's largest open-air rock bas-reliefs, carved onto two monolithic boulders with a natural cleft depicting the cosmic descent of the sacred river. Survived the catastrophic 2004 Indian Ocean Tsunami, which exposed submerged foundational temple blocks offshore. Built using authentic materials: Grey Granite Boulders, Monolithic Diorite Outcrops, Dressed coastal granite blocks.",
      "significance": "Group of Monuments at Mahabalipuram is protected under the Archaeological Survey of India (ASI ID: S-TN-1, UNESCO: 249 (Inscribed 1984)). It stands as a testament to the engineering and cultural prowess of Tamil Nadu.",
      "architecture": "Early Dravidian Pallava Rock-Cut & Structural Architecture — Grey Granite Boulders, Monolithic Diorite Outcrops, Dressed coastal granite blocks",
