      "history": "Constructed during 1799 CE (Late 18th Century) under the royal patronage of Kachwaha Rajput Dynasty (Maharaja Sawai Pratap Singh). Designed by Lal Chand Ustad in the shape of Lord Krishna's crown. The 953 honeycombed jharokha casements allowed royal purdah-observing women to observe daily bazaar life, religious processions, and military parades unseen from the street. The unique microclimate channels harness the Venturi effect, maintaining breezy temperatures even during scorching 45°C Rajasthani summers. Built using authentic materials: Local Pink and Red Banded Sandstone, White Chunam (Lime) plaster detailing.",
