      "history": "Constructed during 6th Century BCE (Origin); Rebuilt 1623 – 1659 CE under the royal patronage of Pandya Dynasty (Origin) & Nayaka Dynasty (Thirumalai Nayak). One of the oldest continuously inhabited sacred temple complexes on earth, forming the epicentre of the ancient lotus-shaped city of Madurai. Sacked in 1310 by Malik Kafur of the Delhi Sultanate, but magnificently rebuilt to cosmic proportions by King Thirumalai Nayak of the Madurai Nayak dynasty in the 17th century. Dedicated to Goddess Meenakshi (Parvati) and Lord Sundareswarar (Shiva). Built using authentic materials: Granite foundation, Stucco plaster polychromatic statues, Teak wood timbering.",
