      "shortStory": "Kakatiya Rudreshwara (Ramappa) Temple is an architectural jewel located in Mulugu District, Palampet, Telangana. Named uniquely after its master sculptor, Ramappa, rather than the deity or the king. Described by Italian merchant Marco Polo as the 'brightest star in the galaxy of medieval temples'. Survived major regional earthquake...",
      "history": "Constructed during 1213 CE (13th Century) under the royal patronage of Kakatiya Dynasty (General Recharla Rudra / King Ganapati Deva). Named uniquely after its master sculptor, Ramappa, rather than the deity or the king. Described by Italian merchant Marco Polo as the 'brightest star in the galaxy of medieval temples'. Survived major regional earthquakes because of its sandbox foundation technology (deep pits filled with sand, granite dust, and jaggery) that absorbed seismic shockwaves. The superstructure bricks are so light and porous they float when dropped in water. Built using authentic materials: Reddish Sandstone plinth, Carved Black Basalt (Dolerite) bracket figures, Ultra-lightweight Porous Floating Bricks.",
      "significance": "Kakatiya Rudreshwara (Ramappa) Temple is protected under the Archaeological Survey of India (ASI ID: H-TL-3, UNESCO: 1570 (Inscribed 2021)). It stands as a testament to the engineering and cultural prowess of Telangana.",
