      "history": "Constructed during 8th Century (Origin); Man Mandir: 1486 – 1516 CE under the royal patronage of Tomara Dynasty (Raja Man Singh Tomar) & Scindia Dynasty. Described by Mughal Emperor Babur as 'the pearl amongst the fortresses of Hind'. Built atop a steep standalone sandstone ridge that controls the route from the Gangetic plains into Malwa. In 1858, legendary warrior queen Rani Lakshmibai of Jhansi fought her final heroic battle against British General Hugh Rose beneath its defensive ramparts. Built using authentic materials: Gwalior Sandstone, Blue, Yellow, and Green Glazed Ceramic Tiles (Kashi work).",
      "significance": "Gwalior Fort & Man Mandir Palace is protected under the Archaeological Survey of India (ASI ID: C-MP-4, UNESCO: Component of Gwalior UNESCO Creative Cities Network). It stands as a testament to the engineering and cultural prowess of Madhya Pradesh.",
