      "shortStory": "Mysore Palace (Amba Vilas Palace) is an architectural jewel located in Mysuru District, Mysuru, Karnataka. Official residence of the Wadiyar dynasty who ruled the Kingdom of Mysore. Built after the old wooden palace burned down during a royal wedding in 1897. Commissioned from British architect Henry Irwin. Famous worldwide f...",
