      "shortStory": "Bishnupur Terracotta Temples is an architectural jewel located in Bankura District, Bishnupur, West Bengal. Because alluvial Bengal lacks hard building stones, Malla kingdom craftsmen transformed fine river silt into baked red terracotta tiles, carving thousands of miniature narrative scenes of Krishna-lila and royal elephant ...",
