      "significance": "Bishnupur Terracotta Temples is protected under the Archaeological Survey of India (ASI ID: E-WB-2, UNESCO: Tentative List (Temples at Bishnupur)). It stands as a testament to the engineering and cultural prowess of West Bengal.",
