      "history": "Constructed during 1530 – 1545 CE (16th Century) under the royal patronage of Vijayanagara Empire (Brothers Virupanna and Veeranna). Built on the tortoiseshell-shaped hill 'Kurma Saila'. Legend states this is where the wounded divine bird Jatayu fell after battling Ravana during Sita's abduction (Lord Rama cried 'Le Pakshi' - Rise Bird). The famous Hanging Pillar hangs detached from the granite floor, supported only by the ceiling cantilever structure, baffling engineers for centuries. Built using authentic materials: Monolithic Granite Gneiss Outcrop (Kurma Saila hill), Fresco tempera pigments.",
