      "shortStory": "Bekal Fort (Sea Bastion of Malabar) is an architectural jewel located in Kasaragod District, Bekal, Kerala. Largest and best-preserved fort in Kerala. Unlike traditional administrative palaces, Bekal was built purely as a military sea defense bastion. Its observation tower at the center was designed so a commander could spot i...",
      "history": "Constructed during 1650 CE (17th Century) under the royal patronage of Keladi Nayakas (Shivappa Nayaka) & Tipu Sultan. Largest and best-preserved fort in Kerala. Unlike traditional administrative palaces, Bekal was built purely as a military sea defense bastion. Its observation tower at the center was designed so a commander could spot incoming naval warships 15 km away, with multi-level embrasures allowing musket and cannon fire at enemy vessels regardless of sea tides. Built using authentic materials: Chiselled Red Laterite Stone Blocks, Lime plaster, Heavy sea masonry.",
      "significance": "Bekal Fort (Sea Bastion of Malabar) is protected under the Archaeological Survey of India (ASI ID: S-KL-1, UNESCO: State Heritage Coastal Monument). It stands as a testament to the engineering and cultural prowess of Kerala.",
