        "Construction Materials: Chiselled Red Laterite Stone Blocks, Lime plaster, Heavy sea masonry",
        "Visiting Guidelines: Open 08:00 AM to 05:30 PM. Beautiful seaside promenade with sunset views over the Arabian Sea.",
