      "significance": "Harappan Bronze 'Dancing Girl' is protected under the Archaeological Survey of India (ASI ID: National Museum Accession No. HR 5721/195, UNESCO: National Treasure of India (Global Icon)). It stands as a testament to the engineering and cultural prowess of Delhi (National Museum).",
