      "shortStory": "Chola Bronze Nataraja (Cosmic Dancer) is an architectural jewel located in Central Delhi / Egmore, Chennai, Delhi & Tamil Nadu (National Museum / Government Museum Chennai). Regarded by philosopher Ananda Coomaraswamy and astrophysicist Carl Sagan as one of the most profound metaphors for modern quantum physics and cosmic cycles of matter. Cast as a single solid piece using the lost-wax tech...",
