      "significance": "Mughal Elephant Combat Armor (Gaj Charma) is protected under the Archaeological Survey of India (ASI ID: National Museum Acc. No. 62.450, UNESCO: World's Largest Historic Animal Armor). It stands as a testament to the engineering and cultural prowess of Delhi & Rajasthan (National Museum / Mehrangarh Museum).",
