      "shortStory": "Champaner-Pavagadh Archaeological Park is an architectural jewel located in Panchmahal District, Champaner, Gujarat. The only complete and unchanged pre-Mughal Islamic capital city in India. Sultan Mahmud Begada besieged the Khichi Chauhan Rajput hilltop fortress of Pavagadh for 20 months before capturing it in 1484, founding his grand...",
      "history": "Constructed during 8th – 16th Century CE under the royal patronage of Chavda / Khichi Chauhan Rajputs & Gujarat Sultanate (Mahmud Begada). The only complete and unchanged pre-Mughal Islamic capital city in India. Sultan Mahmud Begada besieged the Khichi Chauhan Rajput hilltop fortress of Pavagadh for 20 months before capturing it in 1484, founding his grand royal capital Champaner at its base. The Jama Masjid features central dome lanterns that illuminate the prayer hall with daylight while maintaining cool air flow. The Kalika Mata Temple atop Pavagadh peak is a revered ancient Shakti Peetha with a modern ropeway. Built using authentic materials: Local Golden-Yellow Sandstone, Porphyritic basalt rock, Interlocking stone masonry.",
      "significance": "Champaner-Pavagadh Archaeological Park is protected under the Archaeological Survey of India (ASI ID: W-GJ-4, UNESCO: 1101 (Inscribed 2004)). It stands as a testament to the engineering and cultural prowess of Gujarat.",
