      "shortStory": "Adalaj Stepwell (Rudabai Stepwell) is an architectural jewel located in Gandhinagar District, Adalaj, Gujarat. Commissioned by Queen Rudabai, wife of Vaghela chieftain Rana Veer Singh of Dandai Desh. When Veer Singh was killed in battle by Sultan Mahmud Begada, Begada was captivated by Rudabai's beauty and proposed marriage. She ...",
      "history": "Constructed during 1498 CE (Late 15th Century) under the royal patronage of Vaghela Rajput Dynasty (Rani Rudabai) & Mahmud Begada. Commissioned by Queen Rudabai, wife of Vaghela chieftain Rana Veer Singh of Dandai Desh. When Veer Singh was killed in battle by Sultan Mahmud Begada, Begada was captivated by Rudabai's beauty and proposed marriage. She agreed on the condition that he finish the sacred stepwell her husband had begun. Upon its completion in 1498, Rani Rudabai inspected the work, circumambulated the waters, and jumped into the well to join her husband in death rather than submit to the Sultan. Built using authentic materials: Fine Sandstone, Dry-ashlar interlocking stone joints, Lime mortar.",
