        "Construction Materials: Kiln-fired Water-resistant Red Clay Bricks (Standardized 1:2:4 ratio), Gypsum-lime waterproof plaster",
        "Visiting Guidelines: Open 10:00 AM to 05:00 PM (Closed Fridays). On-site ASI Museum displays genuine Harappan carnelian beads, copper fishhoo",
        "Nearby Monument Circuit: Nalsarovar Bird Sanctuary (55 km), Dholka Historic Mosques (30 km), Ahmedabad (85 km)"
