      "shortStory": "Dwarkadhish Temple (Jagat Mandir, Dwarka) is an architectural jewel located in Devbhumi Dwarka District, Dwarka, Gujarat. One of the four sacred Char Dham pilgrimage sites of Hinduism, situated on the western tip of the Saurashtra peninsula where the Gomti River meets the Arabian Sea. Archaeological marine excavations conducted by Dr. S.R. ...",
      "history": "Constructed during Origin: 2,200 years ago; Present structural temple: 15th – 16th Century CE under the royal patronage of Vajranabha (Grandson of Krishna, Traditional) & Chaulukya / Solanki Dynasty. One of the four sacred Char Dham pilgrimage sites of Hinduism, situated on the western tip of the Saurashtra peninsula where the Gomti River meets the Arabian Sea. Archaeological marine excavations conducted by Dr. S.R. Rao of the National Institute of Oceanography (NIO) discovered submerged stone anchors, defensive bastions, and jetty pillars underwater, verifying the epic underwater city of Dwarka described in the Mahabharata. Built using authentic materials: Dressed Limestone and Soft Sandstone, Teak timbering, 52-yard silk flagstaff.",
      "significance": "Dwarkadhish Temple (Jagat Mandir, Dwarka) is protected under the Archaeological Survey of India (ASI ID: W-GJ-8, UNESCO: Char Dham of India & National Sacred Treasure). It stands as a testament to the engineering and cultural prowess of Gujarat.",
