      "shortStory": "Palitana Temples on Shatrunjaya Hill is an architectural jewel located in Bhavnagar District, Palitana, Gujarat. Revered as the holiest of all pilgrimage places (Siddhakshetra) in Jainism, where 23 of the 24 Tirthankaras (except Neminatha) sanctified the hill. It is the only mountain in the world with over 800 temples built atop it...",
      "history": "Constructed during 11th Century CE – Present (spanning 900 years of continuous carving) under the royal patronage of Solanki Kings & Jain Merchant Guilds (Vimal Shah, Vastupala, Tejapala). Revered as the holiest of all pilgrimage places (Siddhakshetra) in Jainism, where 23 of the 24 Tirthankaras (except Neminatha) sanctified the hill. It is the only mountain in the world with over 800 temples built atop it. Every evening at sunset, all priests and devotees must descend the sacred hill—not even the priests are permitted to sleep on the hill at night, leaving the holy city to the gods alone. In 2014, Palitana became the world's first legally 100% vegetarian city. Built using authentic materials: Pure Makrana and Rajasthan White Marble, Intricately carved stone brackets.",
      "significance": "Palitana Temples on Shatrunjaya Hill is protected under the Archaeological Survey of India (ASI ID: Anandji Kalyanji Pedhi / State Heritage, UNESCO: World's Largest Cluster of Temple Shrines on a Single Hill). It stands as a testament to the engineering and cultural prowess of Gujarat.",
