      "shortStory": "Laxmi Vilas Palace is an architectural jewel located in Vadodara District, Vadodara, Gujarat. Constructed over 12 years by Maharaja Sayajirao Gaekwad III at a cost of £180,000 in 1890. Designed by Major Charles Mant (who tragically succumbed to stress believing his calculations were flawed, though the building st...",
      "history": "Constructed during 1890 CE (Late 19th Century) under the royal patronage of Gaekwad Dynasty (Maharaja Sayajirao Gaekwad III / Architect Major Charles Mant). Constructed over 12 years by Maharaja Sayajirao Gaekwad III at a cost of £180,000 in 1890. Designed by Major Charles Mant (who tragically succumbed to stress believing his calculations were flawed, though the building stands flawlessly). It was equipped with the most modern European technologies of its era, including internal hydraulic passenger lifts and complete electric lighting. The estate houses an 18-hole golf course and the world's largest collection of paintings by Raja Ravi Varma. Built using authentic materials: Agra Red Sandstone, Italian Carrara Marble, Belgian Stained Glass, Travertine, Bronze sculptures.",
      "significance": "Laxmi Vilas Palace is protected under the Archaeological Survey of India (ASI ID: Gaekwad Heritage / State Monument, UNESCO: World's Largest Private Residence (Four times the size of Buckingham Palace)). It stands as a testament to the engineering and cultural prowess of Gujarat.",
