      "shortStory": "Sarkhej Roza (The Acropolis of Ahmedabad) is an architectural jewel located in Ahmedabad District, Makarba / Sarkhej, Gujarat. Described by modern architect Le Corbusier as 'the Acropolis of Ahmedabad' due to its perfect proportional harmony and spatial rhythm. Built around the shrine of Sufi saint Sheikh Ahmed Khattu Ganj Baksh, the spiritual a...",
      "history": "Constructed during 1445 – 1510 CE (15th Century) under the royal patronage of Gujarat Sultanate (Sultan Muhammad Shah, Qutbuddin Ahmad Shah, Mahmud Begada). Described by modern architect Le Corbusier as 'the Acropolis of Ahmedabad' due to its perfect proportional harmony and spatial rhythm. Built around the shrine of Sufi saint Sheikh Ahmed Khattu Ganj Baksh, the spiritual advisor who counselled Sultan Ahmed Shah to found Ahmedabad. Uniquely devoid of Persian arches and minarets; instead, it relies completely on indigenous Indian trabeated post-and-beam stone architecture. Built using authentic materials: Local Dhrangadhra Sandstone, Brass jali screens, Interlocking stone pillars.",
