      "shortStory": "Dada Harir Stepwell (Bai Harir Vav) is an architectural jewel located in Ahmedabad District, Asarwa, Gujarat. Constructed by a lady of the royal court, Bai Harir (locally called Dada Harir), who served as the superintendent of Sultan Mahmud Begada's royal household. Features priceless dual stone inscriptions: one in classical Sa...",
