      "shortStory": "Jhulta Minar (The Shaking Minarets of Sidi Bashir) is an architectural jewel located in Ahmedabad District, Sakar Bazar / Sarangpur, Gujarat. One of the most perplexing mechanical engineering mysteries of medieval India: when one minaret is shaken or vibrated gently at the top, the other minaret begins to oscillate in resonance after a few seconds, while the c...",
      "history": "Constructed during 1452 CE (15th Century) under the royal patronage of Gujarat Sultanate (Sidi Bashir, slave of Sultan Ahmed Shah). One of the most perplexing mechanical engineering mysteries of medieval India: when one minaret is shaken or vibrated gently at the top, the other minaret begins to oscillate in resonance after a few seconds, while the connecting stone arch between them remains completely motionless. British engineers in the 19th century even partially dismantled one minaret to discover the secret mechanism but could not decipher the flexible engineering joints, and were unable to put it back together. Built using authentic materials: Yellow Sandstone with deep ornamental stone carvings, Flexible mortar joints.",
      "significance": "Jhulta Minar (The Shaking Minarets of Sidi Bashir) is protected under the Archaeological Survey of India (ASI ID: W-GJ-18, UNESCO: Component of Ahmedabad Heritage Matrix). It stands as a testament to the engineering and cultural prowess of Gujarat.",
