      "shortStory": "Sidhpur Havelis & Rudra Mahalaya Temple Ruins is an architectural jewel located in Patan District, Sidhpur, Gujarat. Sidhpur features two extraordinary architectural paradigms. The Rudra Mahalaya was once the largest and grandest temple in western India, described as a 3-storey temple resting on 1,600 pillars so magnificent that its to...",
      "history": "Constructed during Rudra Mahalaya: 943 – 1140 CE; Havelis: 1880 – 1920 CE under the royal patronage of Solanki Dynasty (Mulraja & Siddharaj Jaisinh) & Dawoodi Bohra Merchant Guilds. Sidhpur features two extraordinary architectural paradigms. The Rudra Mahalaya was once the largest and grandest temple in western India, described as a 3-storey temple resting on 1,600 pillars so magnificent that its torana archways still tower over the town despite being sacked by Alauddin Khilji in 1296. Just 1 km away stand the pastel-hued Dawoodi Bohra havelis—Europe-inspired neoclassical and art nouveau timber mansions built by wealthy sea merchants with imported Belgian glass and Italian balustrades. Built using authentic materials: Giant Sandstone Megaliths, Burnt brick, Burma Teakwood with European pastel stucco.",
      "significance": "Sidhpur Havelis & Rudra Mahalaya Temple Ruins is protected under the Archaeological Survey of India (ASI ID: W-GJ-21, UNESCO: Tentative List (Bohra Havelis of Sidhpur)). It stands as a testament to the engineering and cultural prowess of Gujarat.",
