      "history": "Constructed during 6th Century CE (c. 550 – 575 CE, 1,450 years old) under the royal patronage of Maitraka Dynasty of Vallabhi. Archaeologically revered as the oldest surviving structural stone temple in all of Gujarat. Dating to the mid-6th century CE, it stands on an elevated double terrace overlooking the Vartu River basin. Architecturally fascinating because its tiered pyramidal shikhara exhibits horseshoe arches containing figures that show unmistakable Gandharan-Kashmiri and Gupta influences, indicating ancient trans-continental trade and artistic transmission. Built using authentic materials: Local Yellow Dressed Limestone ashlar blocks laid without mortar, stepped pyramidal roof.",
