      "significance": "Patan Patola Double-Ikat Silk Heritage Textile is protected under the Archaeological Survey of India (ASI ID: Calico Museum Acc. TX-784 / GI Registry #40, UNESCO: Intangible Cultural Heritage of Humanity & GI Tagged). It stands as a testament to the engineering and cultural prowess of Gujarat.",
