      "history": "Constructed during c. 1063 CE (11th Century) under the royal patronage of Chaulukya / Solanki Dynasty (Queen Udayamati). Positioned at the fourth subterranean gallery level of Rani ki Vav, this masterpiece represents the primordial waters of creation (Kshira Sagara). Built by Queen Udayamati as a memorial to her husband Bhima I. The stepwell is conceived as an inverted temple honoring the sanctity of water. Built using authentic materials: White and buff sandstone, fine undercut relief carving.",
